#!/usr/bin/env python3
# luxarch:no-github-issues hook v3 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Escalations, bugs and product requests go in LuxPM. Never a GitHub issue.

PreToolUse(Bash): deny `gh issue create` (or its alias `gh issue new`), a `gh api` call that creates
an issue (a POST to `…/issues` — explicit, or implied by `-f`/`--field`/`--input` — or a GraphQL
`createIssue`) and a curl POST to the API's issue endpoint, however it is quoted and wherever the
shell runs it from (`bash -c`, `$(…)`). LuxPM is the fleet's tracker; GitHub holds code and
Releases and nothing else. A tool call whose event cannot be read is denied.

**Why a hook and not just the standard.** FLEET-ONBOARDING-STANDARD used to sanction
`github.com/luxardolabs/<guard>` as a fallback *"if your repo is not connected to LuxPM yet"*. An
agent took it while its own LuxPM project was live and working, filing four issues across two repos,
and cited the document correctly when challenged. The conditional was the defect: an escape hatch on
an escalation path gets applied wherever it half-fits, and the owner then finds out from the wrong
tracker. The prose is deleted; this is what makes the deletion stick.

It denies CREATION only. Reading is fine and often necessary — `gh issue list` to find what a previous
agent filed in the wrong place, `gh issue view`, and `gh issue delete` to clean it up. A guard that
blocked the cleanup would trap the repair, which is the failure this hook family has shipped before.
"""

from __future__ import annotations

import os
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import (
    executable_segments,
    guarded,
    load_event,
    simple_commands,
    text_field,
    tool_input,
)

# Asked of the MASKED text: "is this verb being RUN?" — a heredoc or a quoted string that merely
# mentions `gh issue create` (a doc being written, this very file) is data, not an execution.
_GH_ISSUE_CREATE = re.compile(r"\bgh\b[^\n]{0,400}?\bissue\b[^\n]{0,400}?\bcreate\b")
# curl against the REST API's issue-creation endpoint, sending data (a POST).
_CURL_ISSUE_POST = re.compile(
    r"\bcurl\b[^\n]{0,400}?api\.github\.com[^\n]{0,400}?/issues(?![/\w])"
)
_CURL_POST = re.compile(
    r"-X[ \t]*POST|--request[ \t]*POST|(?:^|\s)-[dF]\b|--data|--json|--form"
)


def _creates_a_github_issue(masked: str) -> bool:
    if _GH_ISSUE_CREATE.search(masked):
        return True
    return bool(_CURL_ISSUE_POST.search(masked) and _CURL_POST.search(masked))


_GH_VALUE_FLAGS = {"-R", "--repo", "-H", "--header", "--hostname", "-X", "--method", "-f", "-F",
                   "--field", "--raw-field", "--input", "-q", "--jq", "-t", "--template",
                   "--cache", "-p", "--preview"}  # fmt: skip
_CREATE_PATH = re.compile(r"(?:^|/)issues/?$")


def _gh_creates(argv: tuple[str, ...]) -> bool:
    """`gh issue create|new`, or a `gh api` call that creates an issue (a POST to …/issues, or a
    GraphQL `createIssue`), read as argv. Editing, commenting on and closing issues pass."""
    if os.path.basename(argv[0]) != "gh":
        return False
    words: list[str] = []
    skip = False
    for w in argv[1:]:
        if skip:
            skip = False
        elif w in _GH_VALUE_FLAGS:
            skip = True
        elif not w.startswith("-"):
            words.append(w)
    if words[:1] == ["issue"] and words[1:2] in (["create"], ["new"]):
        return True
    if words[:1] != ["api"]:
        return False
    if words[1:2] == ["graphql"]:
        return any("createIssue" in w for w in argv)
    if not any(
        _CREATE_PATH.search(re.split(r"[?#]", w, maxsplit=1)[0]) for w in words[1:]
    ):
        return False
    method = next(
        (argv[i + 1] for i, w in enumerate(argv[:-1]) if w in ("-X", "--method")), ""
    )
    method = method or next(
        (
            w.split("=", 1)[1]
            for w in argv
            if w.startswith(("--method=", "-X")) and len(w) > 2
        ),
        "",
    )
    sends = any(
        w in ("-f", "-F", "--field", "--raw-field", "--input")
        or re.match(r"^-[fF].", w)
        or w.startswith(("--field=", "--raw-field=", "--input="))
        for w in argv
    )
    return method.upper().lstrip("=") == "POST" or (
        sends and not method
    )  # gh POSTs a body


def main() -> int:
    cmd = text_field(tool_input(load_event()), "command")
    if not any(
        _creates_a_github_issue(masked) for masked, _raw in executable_segments(cmd)
    ) and not any(_gh_creates(sc.argv) for sc in simple_commands(cmd)):
        return 0
    print(
        "DENIED: escalations and bug reports go in LuxPM, never GitHub Issues.\n"
        "File it in YOUR OWN repo's LuxPM project with `luxpm_create_issue`, label it "
        "`fleet-escalation`, and name the target guard in the title — the maintainer sweeps that "
        "label across every project and picks it up where you filed it.\n"
        "Escalating about LuxPM itself? It has its own LuxPM project, like every other repo.\n"
        "Genuinely have no LuxPM project? Say so to the owner in one line and keep the full "
        "escalation text in that reply; they create the project and you file it properly. Do not "
        "invent a channel.\n"
        "See luxarch --doc FLEET-ONBOARDING-STANDARD §3a. Reading and DELETING issues is allowed — "
        "only creation is denied, so you can still clean up ones filed in the wrong place.",
        file=sys.stderr,
    )
    return 2


sys.exit(guarded(main, "no-github-issues"))
